'use strict';

// MODULES //

var FLOAT64_MAX = require( '@stdlib/constants/float64/max' );
var normalizeString = require( './normalize_string.js' );


// MAIN //

/**
* Returns default options.
*
* @private
* @returns {Object} default options
*/
function defaults() {
	var out = {};

	// Width "units":
	out.widthUnits = 'columns'; // 'graphemes' || 'columns'

	// Cell alignment:
	out.align = [ 'right' ]; // 'left' || 'right' || 'center'

	// Boolean indicating whether to automatically re-render on a `change` event:
	out.autoRender = false;

	// Border characters:
	out.borders = [
		normalizeString( '-', out.widthUnits ),
		normalizeString( '|', out.widthUnits ),
		normalizeString( '-', out.widthUnits ),
		normalizeString( '|', out.widthUnits )
	];

	// Buffer size:
	out.bufferSize = FLOAT64_MAX;

	// Column separator:
	out.columnSeparator = normalizeString( '|', out.widthUnits );

	// Column widths:
	out.columnWidth = null; // by default, automatically size based on content

	// Corner characters:
	out.corners = [
		normalizeString( '┌', out.widthUnits ),
		normalizeString( '┐', out.widthUnits ),
		normalizeString( '┘', out.widthUnits ),
		normalizeString( '└', out.widthUnits )
	];

	// Cell format string:
	out.format = [ '%s' ];

	// Header alignment:
	out.headerAlign = null;

	// Column headers:
	out.headers = null;

	// Header separator:
	out.headerSeparator = normalizeString( '-', out.widthUnits );

	// Horizontal line separator mode:
	out.horizontalSeparatorMode = 'resume'; // 'interpolate' || 'repeat' || 'resume'

	// Joint characters:
	out.joints = [
		normalizeString( '┼', out.widthUnits ),
		normalizeString( '┬', out.widthUnits ),
		normalizeString( '┤', out.widthUnits ),
		normalizeString( '┴', out.widthUnits ),
		normalizeString( '├', out.widthUnits )
	];

	// Table margins:
	out.margins = [ 0, 0, 0, 0 ];

	// Maximum column width:
	out.maxColumnWidth = [ FLOAT64_MAX ];

	// Maximum table width:
	out.maxWidth = FLOAT64_MAX;

	// Cell padding:
	out.paddingLeft = [ 1 ];
	out.paddingRight = [ 1 ];

	// Row separator:
	out.rowSeparator = normalizeString( '', out.widthUnits );

	// Vertical line separator mode:
	out.verticalSeparatorMode = 'resume'; // 'interpolate' || 'repeat' || 'resume'

	return out;
}


// EXPORTS //

module.exports = defaults;
